/* Local-only matching UI. No matching results or applicant drafts are persisted. */
const matchState={workerId:null,days:14,level:'',openOrderId:null,tab:'jobs',query:'',pickerOpen:false,phoneShown:false,profileOpen:false,excludedOpen:false,cache:new Map(),calculations:0,lastRenderKey:''};
let matchViewRequest=0,matchSearchTimer=null;
const matchWorkerFields=['id','name','gender','birthDate','age','desiredJob1','desiredJob2','desiredJob3','desiredJob','cantonese','mandarin','english','otherLanguages','workHistory','workedHongKong','hkEmployer','hkExitDate','certificates','skills','desiredSalary','height','weight','education','health','hometown','marital','phone','photo','educationHistory','hobbies','matchProfile'];
const matchOrderFields=['id','code','title','employer','gender','age','language','salary','workContent','requirements','notes','createdAt','matchProfile'];
const matchMarks=ZYMatching.marks,matchLevelLabels={high:'高',mid:'中',low:'低'},matchDots={high:'●●●',mid:'●●○',low:'●○○'};
const matchCopyFields=(value,keys)=>Object.fromEntries(keys.map(k=>[k,value[k]]));
const selectedMatchWorker=()=>workers.find(w=>w.id===matchState.workerId);
function canEditMatchWorker(){return ['admin','staff'].includes(sessionUser?.role)&&!sessionUser?.readOnly}
function matchValue(value){return String(value??'').trim()}
function matchPhone(worker){const phone=matchValue(worker.phone);return phone?'****'+phone.replace(/\D/g,'').slice(-4):''}
function matchAgeText(worker){const age=ZYMatching.workerAge(worker);return age===null?'—':age+'岁'}
function matchWorkerLabel(worker){return [worker.name,worker.gender,matchAgeText(worker)].filter(Boolean).join(' · ')}
function matchReason(reason){return `<span data-match-reason data-user-content data-template="${esc(reason.template)}" data-values="${esc(JSON.stringify(reason.values||{}))}">${esc(reason.text)}</span>`}
function matchGeneratedValue(template,key,value){
 if(ZYI18n.language!=='en')return String(value??'');const raw=String(value??'');
 if(template==='要求{required}，劳工为{actual}')return raw==='男性'?'male':raw==='女性'?'female':raw;
 if(key==='gap')return raw==='达到要求'?'meets requirement':raw.replace(/^差(\d+)级$/,'$1 level(s) below');
 if(key==='duration')return raw==='时长不明，按12个月'?'unknown duration; 12 months assumed':raw.replace(/^约/,'approx. ').replace(/(\d+)年(\d+)个月/,'$1 years $2 months');
 if(key==='end')return raw==='至今'?'current':raw==='结束时间不明'?'end date unknown':raw.replace(/(\d+)年离职/,'left in $1');
 return raw==='未填写'?'not provided':raw;
}
function localiseMatchReasons(){
 document.querySelectorAll('[data-match-reason]').forEach(node=>{
  const signature=ZYI18n.language+'|'+node.dataset.template+'|'+node.dataset.values;if(node.dataset.localized===signature)return;
  const values=JSON.parse(node.dataset.values||'{}'),template=node.dataset.template,text=ZYI18n.translate(template).replace(/\{n\} (orders|days)/g,(part,word)=>Number(values.n)===1?'{n} '+word.slice(0,-1):part),pieces=text.split(/(\{\w+\})/g);
  node.innerHTML=pieces.map(piece=>/^\{\w+\}$/.test(piece)?`<span data-user-content>${esc(matchGeneratedValue(template,piece.slice(1,-1),values[piece.slice(1,-1)]))}</span>`:esc(piece)).join('');node.dataset.localized=signature;
 });document.querySelectorAll('.match-explanation').forEach(el=>{if(el.title!==el.textContent)el.title=el.textContent});
}
function openWorkerMatch(id){const previous={workerId:matchState.workerId,phoneShown:matchState.phoneShown,openOrderId:matchState.openOrderId,level:matchState.level,tab:matchState.tab};matchState.workerId=id||null;matchState.phoneShown=false;matchState.openOrderId=null;matchState.level='';matchState.tab='jobs';if(go('match')===false){Object.assign(matchState,previous);return false}}
function workerSavedToast(id){toast('劳工资料已保存');const link=document.createElement('button');link.type='button';link.textContent='去匹配岗位';link.onclick=()=>openWorkerMatch(id);$('.toast')?.append(' ',link)}
async function matchView({load=true,sync=false}={}){
 const request=++matchViewRequest,userId=sessionUser?.id;
 if(load){if(!$('#match-workspace'))$('#content').innerHTML='<p role="status">正在读取劳工资料…</p>';try{await loadWorkers()}catch{if(view==='match'&&sessionUser?.id===userId)$('#content').innerHTML='<p>劳工资料读取失败，请重试</p><button onclick="matchView()">重试</button>';return}}
 if(view!=='match'||sessionUser?.id!==userId||request!==matchViewRequest)return;
 if(matchState.workerId&&!selectedMatchWorker()){matchState.workerId=null;matchState.openOrderId=null;matchState.phoneShown=false;matchState.cache.clear();toast('所选劳工已被删除')}
 renderMatchPage({sync});
}
function matchBundle(){
 const selected=selectedMatchWorker();if(!selected)return {key:'empty|'+JSON.stringify(workers.map(w=>[w.id,w.name,matchPhone(w)])),results:[],orders:new Map()};
 const worker=matchCopyFields(selected,matchWorkerFields),key=JSON.stringify(worker)+'|'+revision+'|'+matchState.days+'|'+ZYTime.todayKey();
 if(matchState.cache.has(key))return matchState.cache.get(key);
 const ready=orders.filter(o=>orderState(o)==='ready').map(o=>matchCopyFields(orderPublication(o).order,matchOrderFields));
 const results=ZYMatching.matchWorker(worker,ready,{days:matchState.days,today:ZYTime.todayKey()}),bundle={key,results,orders:new Map(ready.map(o=>[o.id,o]))};
 matchState.calculations++;matchState.cache.set(key,bundle);if(matchState.cache.size>8)matchState.cache.delete(matchState.cache.keys().next().value);return bundle;
}
function renderMatchPage({sync=false}={}){
 const bundle=matchBundle();if(sync&&$('#match-workspace')&&bundle.key===matchState.lastRenderKey){if(matchState.pickerOpen)renderWorkerChoices();return}
 const focused=document.activeElement?.id,searchValue=$('#match-worker-search')?.value,scrollYBefore=scrollY,profileScroll=$('#match-profile-body')?.scrollTop||0;
 const selected=selectedMatchWorker(),matching=bundle.results.filter(r=>!r.excluded),excluded=bundle.results.filter(r=>r.excluded),open=matching.find(r=>r.orderId===matchState.openOrderId);
 if(matchState.openOrderId&&!open)matchState.openOrderId=null;if(bundle.key!==matchState.lastRenderKey&&!matching.length&&excluded.length)matchState.excludedOpen=true;
 const workerLabel=selected?matchWorkerLabel(selected):'',total=bundle.results.length;
 $('#content').innerHTML=`<div id="match-workspace"><div class="match-toolbar"><h1>岗位匹配</h1><div class="match-picker"><input id="match-worker-search" role="combobox" aria-label="选择劳工，搜索姓名或电话后4位" aria-autocomplete="list" aria-expanded="${matchState.pickerOpen}" aria-controls="match-worker-options" autocomplete="off" placeholder="选择劳工，搜索姓名或电话后4位" value="${esc(matchState.pickerOpen?matchState.query:workerLabel)}" onfocus="showWorkerChoices()" oninput="queueWorkerChoices(this.value)" onkeydown="matchPickerKeys(event)"><div id="match-worker-options" role="listbox" aria-label="已登记劳工" ${matchState.pickerOpen?'':'hidden'}></div></div><div class="match-range" role="group" aria-label="公司单范围">${[7,14,30].map(days=>`<button data-match-days="${days}" aria-pressed="${matchState.days===days}" onclick="setMatchRange(${days})">${matchReason({template:'最近{n}天',values:{n:days},text:'最近'+days+'天'})}</button>`).join('')}</div></div><div class="match-mobile-tabs" role="tablist" aria-label="岗位匹配内容"><button role="tab" aria-selected="${matchState.tab==='jobs'}" onclick="setMatchTab('jobs')">匹配岗位 <span data-user-content>${matching.length}</span></button><button role="tab" aria-selected="${matchState.tab==='profile'}" onclick="setMatchTab('profile')">劳工资料</button></div>${!workers.length?'<div class="panel empty">还没有已登记的劳工<div class="actions"><button class="primary" onclick="go(\'workers\')">去劳工登记</button></div></div>':`<div class="match-columns" data-tab="${matchState.tab}"><section class="match-results" aria-label="匹配岗位">${!selected?'<div class="panel empty">请选择一位已登记劳工</div>':!ZYMatching.histories(selected).length?`<div class="panel empty">请补充工作经历后再匹配<div class="actions">${canEditMatchWorker()?`<button onclick="editWorker(${jsValue(selected.id)})">补充资料</button>`:''}</div></div>`:`${matching.some(r=>r.sparse)?`<div class="note match-sparse">这位劳工资料较少，匹配结果仅供参考 ${canEditMatchWorker()?`<button onclick="editWorker(${jsValue(selected.id)})">补充资料</button>`:''}</div>`:''}<div class="match-filter"><div class="match-chips">${[['','全部'],['high','高'],['mid','中'],['low','低']].map(([level,label])=>`<button data-match-level="${level}" aria-pressed="${matchState.level===level}" onclick="setMatchLevel('${level}')"><span aria-hidden="true">${matchDots[level]||''}</span> <span>${label}</span> <b data-user-content>${level?matching.filter(r=>r.level===level).length:matching.length}</b></button>`).join('')}</div><small>${matchReason({template:'只匹配可发布的公司单 · 共{n}张',values:{n:total},text:'只匹配可发布的公司单 · 共'+total+'张'})}</small></div>${!total?`<div class="panel empty">${matchReason({template:'最近{n}天没有可发布的公司单',values:{n:matchState.days},text:'最近'+matchState.days+'天没有可发布的公司单'})}<div class="actions"><button onclick="setMatchRange(30)">切换到30天</button></div></div>`:!matching.length?'<p class="note">没有符合的岗位</p>':''}${matching.length?`<div class="match-table-scroll"><div class="match-table"><div class="match-grid match-table-head" aria-hidden="true"><span>匹配度</span><span>职位 · 雇主</span><span>月薪</span><span>依据</span><span>分数</span><span>操作</span></div>${['high','mid','low'].filter(level=>!matchState.level||matchState.level===level).map(level=>{const group=matching.filter(r=>r.level===level);return !group.length?'':`<section class="match-group match-${level}"><h2><span aria-hidden="true">${matchDots[level]}</span> <span>${{high:'高匹配（75分以上）',mid:'中匹配（50分以上）',low:'低匹配（50分以下）'}[level]}</span><span data-user-content>${group.length}</span></h2>${group.map(result=>matchRow(result,bundle.orders.get(result.orderId))).join('')}</section>`}).join('')}</div></div>`:''}${excluded.length?`<details class="match-excluded" ${matchState.excludedOpen?'open':''} ontoggle="if(this.isConnected)matchState.excludedOpen=this.open"><summary>${matchReason({template:'另有{n}张不符合未计分',values:{n:excluded.length},text:'另有'+excluded.length+'张不符合未计分'})}<span>查看原因</span></summary>${excluded.map(r=>{const o=bundle.orders.get(r.orderId);return `<p class="match-excluded-row"><span data-user-content>${esc(o.title)} · ${esc(o.salary)}</span> · ${r.reasonDetails.map(matchReason).join('；')}</p>`}).join('')}</details>`:''}<p class="match-rule-note">硬条件：性别、年龄、相关工作经历。经历占70%，明确条件占30%，意向最多加10分。高：同类经历且≥75分；中：≥50分；仅相关类经历最高为中。</p>`}</section><aside class="match-profile" aria-label="劳工资料">${selected?matchProfile(selected,open,bundle):'<div class="panel empty">请选择一位已登记劳工</div>'}</aside></div>`}</div>`;
 matchState.lastRenderKey=bundle.key;renderWorkerChoices();localiseMatchReasons();fitMatchProfile();if(sync){window.scrollTo(0,scrollYBefore);if($('#match-profile-body'))$('#match-profile-body').scrollTop=profileScroll;if(focused)document.getElementById(focused)?.focus({preventScroll:true});if(focused==='match-worker-search'&&searchValue!==undefined)$('#match-worker-search').value=searchValue}
}
function matchRow(result,order){
 const id=jsValue(result.orderId),expanded=result.orderId===matchState.openOrderId;
 const tagDims=[{...result.experience,label:'经历'},...result.conditions.items,{...result.intent,label:'意向',mark:result.intent.bonus?'bonus':'unknown'}].slice(0,4);
 const tags=tagDims.map(d=>`<span class="match-tag mark-${d.mark}"><span>${esc(d.label)}</span>${d.mark==='bonus'?'+':matchMarks[d.mark]}</span>`).join('');
 const bar=d=>`<div class="match-dimension"><b>${d.label}</b><span class="match-bar" aria-hidden="true"><i style="width:${d.got===null?0:100*d.got/d.max}%;background:${d.got/d.max>=.75?'var(--ready-dot)':d.got/d.max>=.4?'var(--brand)':'var(--match-bar-low)'}"></i></span><span class="numeric" data-user-content>${d.displayGot===null?'—':d.displayGot}/${d.max}</span><span class="match-tag mark-${d.mark}">${matchMarks[d.mark]}</span><span class="match-explanation" tabindex="0">${d.reasons.map(matchReason).join('；')}</span></div>`;
 return `<article class="match-entry ${expanded?'expanded':''}" data-match-order="${esc(result.orderId)}"><div class="match-grid match-row" onclick="matchRowClick(event,${id})"><span class="match-level level-${result.level}"><i aria-hidden="true">${matchDots[result.level]}</i> <span>${matchLevelLabels[result.level]}</span></span><button class="match-order-open" aria-expanded="${expanded}" onclick="toggleMatchOrder(${id})"><strong data-user-content title="${esc(order.title)}">${esc(order.title)}</strong>${order.employer?`<span class="match-employer" data-user-content title="${esc(order.employer)}">${esc(order.employer)}</span>`:''}</button><span class="match-salary" data-user-content title="${esc(order.salary)}">${esc(order.salary)}</span><div class="match-tags">${tags}</div><span class="match-score numeric" data-user-content>${result.score}</span><button class="primary match-copy" onclick="copyOrder(${id})">复制</button></div>${expanded?`<div class="match-breakdown">${result.hardChecks.length?`<p class="note">${result.hardChecks.map(matchReason).join('；')}</p>`:''}${bar(result.experience)}${result.experience.by==='ai'?'<span class="match-tag" data-user-content>AI</span>':''}${!ZYMatching.profileFor(order,'order').valid&&canEditMatchWorker()?`<button onclick="reanalyzeMatchOrder(${id})">重新分析</button>`:''}<h3>岗位条件</h3>${result.conditions.items.length?result.conditions.items.map(c=>`<p class="match-condition"><span class="match-tag mark-${c.mark}">${matchMarks[c.mark]}</span> ${matchReason(c.reason)}${c.by==='ai'?'<span data-user-content> AI</span>':''}</p>`).join(''):'<p>公司单未写其他条件</p>'}<h3>意向加分</h3><p><span data-user-content>+${result.intent.bonus}</span> ${result.intent.reasons.map(matchReason).join('；')}</p><button class="match-profile-link" onclick="setMatchTab('profile')">在劳工资料中查看</button></div>`:''}</article>`;
}

function matchProfile(worker,open,bundle){
 const small=matchMedia('(max-width:639px)').matches,desktop=matchMedia('(min-width:1100px)').matches,experience=open?.dims.find(d=>d.key==='experience'),language=open?.language,selectedHistory=experience?.histories||[],missing=[...new Set((open?[open]:bundle.results.filter(r=>!r.excluded)).flatMap(r=>r.dims.flatMap(d=>d.missing||[])))];
 const labelValue=(label,value)=>`<dt>${label}</dt><dd ${value?'data-user-content':''}>${value?esc(value):'未填写'}</dd>`;
 const allHistories=ZYMatching.histories(worker),photo=/^data:image\/(jpeg|png|webp);base64,/i.test(worker.photo||'')?`<img src="${esc(worker.photo)}" alt="劳工照片">`:`<span class="match-avatar" data-user-content>${esc(Array.from(worker.name||'—')[0])}</span>`;
 return `<${small||desktop?'section':'details'} ${small||desktop||matchState.profileOpen?'open':''} class="match-profile-shell" ontoggle="if(this.isConnected&&matchMedia('(min-width:640px) and (max-width:1099px)').matches)matchState.profileOpen=this.open"><summary><span data-user-content>${esc(matchWorkerLabel(worker))} · ${esc([worker.desiredJob1||worker.desiredJob,worker.desiredJob2,worker.desiredJob3].filter(Boolean).join(' / '))}</span></summary><div class="match-profile-body" id="match-profile-body" tabindex="-1"><div class="match-person">${photo}<div><h2 data-user-content>${esc(worker.name)}</h2>${!ZYMatching.profileFor(worker,'worker').valid&&canEditMatchWorker()?`<button class="match-reanalyze" onclick="reanalyzeMatchWorker()">重新分析</button>`:''}<p class="match-person-summary" data-user-content title="${esc([worker.gender,matchAgeText(worker),worker.hometown,worker.health,worker.education].filter(Boolean).join(' · '))}">${esc([worker.gender,matchAgeText(worker),worker.hometown,worker.health,worker.education].filter(Boolean).join(' · '))}</p></div></div><p class="match-phone"><span>联系电话</span> <span data-user-content>${esc(matchState.phoneShown?worker.phone:matchPhone(worker))||'—'}</span>${worker.phone?`<button aria-pressed="${matchState.phoneShown}" onclick="toggleMatchPhone()">${matchState.phoneShown?'隐藏':'显示'}</button>`:''}</p><h3>求职意向</h3><div class="match-intents">${[worker.desiredJob1||worker.desiredJob,worker.desiredJob2,worker.desiredJob3].map((intent,i)=>`<span class="match-intent ${open?.matchedIntentIndex===i?'matched':''}" data-intent-index="${i}"><span data-user-content>${i+1} · ${esc(intent||'—')}</span></span>`).join('')}</div><p><span>期望薪金</span> <span data-user-content>${esc(worker.desiredSalary)||'—'}</span></p><h3>语言能力</h3>${[['cantonese','粤语'],['mandarin','普通话'],['english','英语']].map(([key,label])=>{const level=ZYMatching.languageLevel(worker[key]);return `<div class="match-language ${language?.satisfiedLanguages.includes(key)?'matched':''}" data-language-key="${key}"><span>${label}</span><span class="match-language-bars" aria-hidden="true">${Array.from({length:5},(_,i)=>`<i class="${level!==null&&i<Math.round(level/4*5)?'filled':''}"></i>`).join('')}</span><b data-user-content>${esc(worker[key])||'—'}</b></div>`}).join('')}${worker.otherLanguages?`<p><span>其他语言</span> <span data-user-content>${esc(worker.otherLanguages)}</span></p>`:''}<h3>工作经历</h3>${allHistories.length?allHistories.map(h=>{const used=selectedHistory.find(r=>r.index===h.index);return `<div class="match-history ${used?'matched':''}" data-history-index="${h.index}"><div><strong data-user-content>${esc(h.position||'—')}</strong> <span data-user-content>${esc(h.employer||'')}</span><time data-user-content>${esc(h.period||'—')}</time></div><p data-user-content title="${esc(h.duties||'')}">${esc(h.duties||'')}</p>${used?`<small>${matchReason({template:'与当前岗位相关 · {duration}',values:{duration:used.periodInfo.unknown?'时长不明，按12个月':Math.floor(used.periodInfo.months/12)+'年'+used.periodInfo.months%12+'个月'},text:'与当前岗位相关'})}</small>`:''}</div>`}).join(''):'<p>未填写工作经历</p>'}<h3>其他资料</h3><dl class="match-worker-details">${labelValue('香港劳务经历',worker.workedHongKong)}${labelValue('香港雇主',worker.hkEmployer)}${labelValue('离港日期',worker.hkExitDate)}${labelValue('专业证书',worker.certificates||worker.skills)}${labelValue('最高学历',worker.education)}${labelValue('身高',worker.height)}${labelValue('体重',worker.weight)}${labelValue('特长爱好',worker.hobbies)}</dl><h3>教育经历</h3>${(worker.educationHistory||[]).map(h=>`<p data-user-content>${esc([h.period,h.school,h.major,h.qualification].filter(Boolean).join(' · '))}</p>`).join('')||'<p>未填写</p>'}${missing.length?`<div class="match-missing"><b>资料不全</b><p>${missing.map(label=>`<span>${label}</span>`).join(' · ')}</p><small>未填写的条件不计入条件分</small></div>`:''}</div><div class="match-profile-actions">${canEditMatchWorker()?`<button onclick="editWorker(${jsValue(worker.id)})">编辑资料</button>`:''}<button onclick="previewMatchWorker()">预览登记表</button></div></${small||desktop?'section':'details'}>`;
}
function fitMatchProfile(){const profile=$('.match-profile');if(view!=='match'||!profile||!matchMedia('(min-width:1100px)').matches)return;profile.style.setProperty('--match-profile-height',Math.max(160,innerHeight-Math.max(20,profile.getBoundingClientRect().top)-20)+'px')}
addEventListener('resize',fitMatchProfile);
function matchRowClick(event,id){if(matchMedia('(max-width:639px)').matches&&!event.target.closest('button'))toggleMatchOrder(id)}
function previewMatchWorker(){const selected=selectedMatchWorker();if(!selected)return;const preview=matchCopyFields(selected,matchWorkerFields);preview.phone=matchState.phoneShown?selected.phone:matchPhone(selected);preview.age=String(ZYMatching.workerAge(selected)??'');if(!/^data:image\/(jpeg|png|webp);base64,/i.test(preview.photo||''))delete preview.photo;previewWorker(preview)}
function setMatchRange(days){matchState.days=days;matchState.openOrderId=null;matchState.excludedOpen=false;renderMatchPage()}
function setMatchLevel(level){matchState.level=level;matchState.openOrderId=null;renderMatchPage()}
function toggleMatchOrder(id){matchState.openOrderId=matchState.openOrderId===id?null:id;renderMatchPage();if(!matchMedia('(max-width:639px)').matches){const el=[...document.querySelectorAll('.match-entry')].find(e=>e.dataset.matchOrder===id);el?.querySelector('.match-order-open')?.focus({preventScroll:true})}}
function setMatchTab(tab){matchState.tab=tab;renderMatchPage();if(tab==='profile')$('#match-profile-body')?.focus({preventScroll:true});else $('.match-mobile-tabs button[aria-selected="true"]')?.focus({preventScroll:true})}
function toggleMatchPhone(){matchState.phoneShown=!matchState.phoneShown;renderMatchPage();$('.match-phone button')?.focus({preventScroll:true})}
function showWorkerChoices(){matchState.pickerOpen=true;$('#match-worker-options').hidden=false;$('#match-worker-search').setAttribute('aria-expanded','true');renderWorkerChoices()}
function queueWorkerChoices(value){matchState.query=value;clearTimeout(matchSearchTimer);matchSearchTimer=setTimeout(()=>{if(view==='match')renderWorkerChoices()},200)}
function renderWorkerChoices(){
 const box=$('#match-worker-options');if(!box)return;box.hidden=!matchState.pickerOpen;if(!matchState.pickerOpen)return;
 const q=matchState.query.trim().toLowerCase(),list=workers.filter(w=>matchValue(w.name).toLowerCase().includes(q)||/^\d{1,4}$/.test(q)&&matchValue(w.phone).replace(/\D/g,'').slice(-4).includes(q));
 box.innerHTML=list.map(w=>`<button role="option" aria-selected="${w.id===matchState.workerId}" data-match-worker="${esc(w.id)}" onclick="selectMatchWorker(${jsValue(w.id)})" data-user-content>${esc(matchWorkerLabel(w))} · ${esc(matchPhone(w))}</button>`).join('')||'<p>没有找到劳工</p>';
}
function selectMatchWorker(id){matchState.workerId=id;matchState.pickerOpen=false;matchState.query='';matchState.phoneShown=false;matchState.openOrderId=null;matchState.level='';matchState.tab='jobs';renderMatchPage();$('#match-worker-search')?.focus({preventScroll:true});matchState.pickerOpen=false;$('#match-worker-options').hidden=true;$('#match-worker-search').setAttribute('aria-expanded','false')}
function matchPickerKeys(event){const box=$('#match-worker-options'),items=[...box.querySelectorAll('button')];if(event.key==='ArrowDown'){event.preventDefault();showWorkerChoices();box.querySelector('button')?.focus()}if(event.key==='Escape'){matchState.pickerOpen=false;box.hidden=true;event.target.setAttribute('aria-expanded','false')}}
addEventListener('keydown',event=>{if(!event.target.closest('#match-worker-options'))return;const items=[...$('#match-worker-options').querySelectorAll('button')],at=items.indexOf(document.activeElement);if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();items[(at+(event.key==='ArrowDown'?1:items.length-1))%items.length]?.focus()}if(event.key==='Escape'){event.preventDefault();matchState.pickerOpen=false;$('#match-worker-options').hidden=true;$('#match-worker-search').focus();matchState.pickerOpen=false;$('#match-worker-options').hidden=true;$('#match-worker-search').setAttribute('aria-expanded','false')}});
addEventListener('click',event=>{if(view==='match'&&!event.target.closest('.match-picker')){matchState.pickerOpen=false;$('#match-worker-options')?.setAttribute('hidden','');$('#match-worker-search')?.setAttribute('aria-expanded','false')}});
for(const query of ['(max-width:639px)','(min-width:1100px)'])matchMedia(query).addEventListener('change',()=>{if(view==='match'&&$('#match-workspace'))renderMatchPage()});
window.ZYMatchUI={localise:localiseMatchReasons,leave(){matchState.phoneShown=false;matchState.pickerOpen=false},reset(){matchViewRequest++;clearTimeout(matchSearchTimer);Object.assign(matchState,{workerId:null,days:14,level:'',openOrderId:null,tab:'jobs',phoneShown:false,pickerOpen:false,query:'',profileOpen:false,excludedOpen:false,lastRenderKey:''});matchState.cache.clear();$('#match-workspace')?.remove()}};

async function reanalyzeMatchWorker(){const w=selectedMatchWorker();if(!w||!canEditMatchWorker())return;const id=w.id,hash=ZYMatching.sourceHash(w,'worker'),profile=await ZYAI.analyzeMatch(w,'worker');if(!profile)return;const fresh=(await api('/api/workers')).workers.find(x=>x.id===id);if(!fresh||ZYMatching.sourceHash(fresh,'worker')!==hash)return;try{await dbWrite('put',{...fresh,matchProfile:profile});await matchView()}catch(e){toast(e.message)}}

async function reanalyzeMatchOrder(id){if(!canEditMatchWorker())return;const original=orders.find(o=>o.id===id);if(!original)return;const presented=orderPublication(original).order,hash=ZYMatching.sourceHash(presented,'order'),profile=await ZYAI.analyzeMatch(presented,'order');if(!profile)return;const fresh=orders.find(o=>o.id===id);if(!fresh||ZYMatching.sourceHash(orderPublication(fresh).order,'order')!==hash)return;const before=orders;orders=orders.map(o=>o.id===id?{...o,matchProfile:profile}:o);if(!await persist()){orders=before;return}renderMatchPage()}
